//ARVALID MUX 
reg [SLAVE_NUM-1:0]ARVALIDsi2mi; 

//MUX TYPE 00 was Generated 
always @(CtlData2writech  or 
         ARVALIDm2si  )
begin

    if(CtlData2writech [SLAVE_WID]) //MUX enalbe bit
    begin
        case(CtlData2writech [SLAVE_WID-1:0])
        //synopsys parallel_case full_case
            3'd0:   
            begin
                 ARVALIDsi2mi[0] <= ARVALIDm2si ;
                 ARVALIDsi2mi[1] <= 1'b0;
                 ARVALIDsi2mi[2] <= 1'b0;
                 ARVALIDsi2mi[3] <= 1'b0;
                 ARVALIDsi2mi[4] <= 1'b0;
                 ARVALIDsi2mi[5] <= 1'b0;
            end
            3'd1:   
            begin
                 ARVALIDsi2mi[0] <= 1'b0;
                 ARVALIDsi2mi[1] <= ARVALIDm2si ;
                 ARVALIDsi2mi[2] <= 1'b0;
                 ARVALIDsi2mi[3] <= 1'b0;
                 ARVALIDsi2mi[4] <= 1'b0;
                 ARVALIDsi2mi[5] <= 1'b0;
            end
            3'd2:   
            begin
                 ARVALIDsi2mi[0] <= 1'b0;
                 ARVALIDsi2mi[1] <= 1'b0;
                 ARVALIDsi2mi[2] <= ARVALIDm2si ;
                 ARVALIDsi2mi[3] <= 1'b0;
                 ARVALIDsi2mi[4] <= 1'b0;
                 ARVALIDsi2mi[5] <= 1'b0;
            end
            3'd3:   
            begin
                 ARVALIDsi2mi[0] <= 1'b0;
                 ARVALIDsi2mi[1] <= 1'b0;
                 ARVALIDsi2mi[2] <= 1'b0;
                 ARVALIDsi2mi[3] <= ARVALIDm2si ;
                 ARVALIDsi2mi[4] <= 1'b0;
                 ARVALIDsi2mi[5] <= 1'b0;
            end
            3'd4:   
            begin
                 ARVALIDsi2mi[0] <= 1'b0;
                 ARVALIDsi2mi[1] <= 1'b0;
                 ARVALIDsi2mi[2] <= 1'b0;
                 ARVALIDsi2mi[3] <= 1'b0;
                 ARVALIDsi2mi[4] <= ARVALIDm2si ;
                 ARVALIDsi2mi[5] <= 1'b0;
            end
            default:
            begin
                ARVALIDsi2mi[0] <= 1'b0;
                ARVALIDsi2mi[1] <= 1'b0;
                ARVALIDsi2mi[2] <= 1'b0;
                ARVALIDsi2mi[3] <= 1'b0;
                ARVALIDsi2mi[4] <= 1'b0;
                ARVALIDsi2mi[5] <= ARVALIDm2si ;
            end
        endcase
    end
    else
    begin
        ARVALIDsi2mi[0] <= 1'b0;
        ARVALIDsi2mi[1] <= 1'b0;
        ARVALIDsi2mi[2] <= 1'b0;
        ARVALIDsi2mi[3] <= 1'b0;
        ARVALIDsi2mi[4] <= 1'b0;
        ARVALIDsi2mi[5] <= 1'b0;
