end


reg ARREADYsi2m;

//ARREADY Demux
always @(CtlData2writech or ARREADYmi2si)
begin
    if(CtlData2writech[SLAVE_WID])
    begin
        case(CtlData2writech[SLAVE_WID-1:0])
        // synopsys parallel_case full_case
            3'd0:   ARREADYsi2m <= ARREADYmi2si[0]; 
            3'd1:   ARREADYsi2m <= ARREADYmi2si[1]; 
            3'd2:   ARREADYsi2m <= ARREADYmi2si[2]; 
            3'd3:   ARREADYsi2m <= ARREADYmi2si[3]; 
            3'd4:   ARREADYsi2m <= ARREADYmi2si[4]; 
            3'd5:   ARREADYsi2m <= ARREADYmi2si[5]; 
            default:
                ARREADYsi2m <= 1'b0;
        endcase
    end
    else
        ARREADYsi2m <= 1'b0;
end

reg [SLAVE_WID-1:0] SlaveNum;

//ADDRESS Decoder
//____________________________________________________________________

//Slave Number 0
wire Slave0MAXEn = (ARADDRm2si >= 32'h0) ? 1'b1:1'b0;
wire Slave0MINEn = (32'h1FFFFFFF >  ARADDRm2si)  ? 1'b1:1'b0;
wire Slave0En = Slave0MAXEn & Slave0MINEn;

//Slave Number 1
wire Slave1MAXEn = (ARADDRm2si >= 32'h20000000) ? 1'b1:1'b0;
wire Slave1MINEn = (32'h3FFFFFFF >  ARADDRm2si)  ? 1'b1:1'b0;
wire Slave1En = Slave1MAXEn & Slave1MINEn;

//Slave Number 2
wire Slave2MAXEn = (ARADDRm2si >= 32'h40000000) ? 1'b1:1'b0;
wire Slave2MINEn = (32'h5FFFFFFF >  ARADDRm2si)  ? 1'b1:1'b0;
wire Slave2En = Slave2MAXEn & Slave2MINEn;

//Slave Number 3
wire Slave3MAXEn = (ARADDRm2si >= 32'h60000000) ? 1'b1:1'b0;
wire Slave3MINEn = (32'h7FFFFFFF >  ARADDRm2si)  ? 1'b1:1'b0;
wire Slave3En = Slave3MAXEn & Slave3MINEn;

//Slave Number 4
wire Slave4MAXEn = (ARADDRm2si >= 32'h80000000) ? 1'b1:1'b0;
wire Slave4MINEn = (32'h9FFFFFFF >  ARADDRm2si)  ? 1'b1:1'b0;
wire Slave4En = Slave4MAXEn & Slave4MINEn;


wire Slave5En = 
                !Slave0En &
                !Slave1En &
                !Slave2En &
                !Slave3En &
                !Slave4En ;

always @(
         Slave0En or
         Slave1En or
         Slave2En or
         Slave3En or
         Slave4En or
         Slave5En  
        )
begin
    case(1'b1)
        Slave0En:   SlaveNum <= 3'd0;
        Slave1En:   SlaveNum <= 3'd1;
        Slave2En:   SlaveNum <= 3'd2;
        Slave3En:   SlaveNum <= 3'd3;
        Slave4En:   SlaveNum <= 3'd4;
        Slave5En:   SlaveNum <= 3'd5;
    endcase
end

