//Data Arbiter
reg   [SLAVE_WID-1:0] CtlData2readch; 

//Response Arbiter
//Arbiter was Generated TYPE00
reg   EnArbiter;

always @(
         RVALIDmi2si or
         CtlData2readch
        )
begin
    case(CtlData2readch)
        //synopsys parallel_case full_case
        3'd0:    EnArbiter <= RVALIDmi2si[0];
        3'd1:    EnArbiter <= RVALIDmi2si[1];
        3'd2:    EnArbiter <= RVALIDmi2si[2];
        3'd3:    EnArbiter <= RVALIDmi2si[3];
        3'd4:    EnArbiter <= RVALIDmi2si[4];
        3'd5:    EnArbiter <= RVALIDmi2si[5];
        default: EnArbiter <= 1'b0;
    endcase
end

always  @(posedge ACLK or negedge ARESETn)
begin
    if(!ARESETn)
    begin
        CtlData2readch <= 0;
    end
    else if(!EnArbiter)
    begin
          if(RVALIDmi2si[0]) CtlData2readch <= 3'd0;
          else if(RVALIDmi2si[1]) CtlData2readch <= 3'd1;
          else if(RVALIDmi2si[2]) CtlData2readch <= 3'd2;
          else if(RVALIDmi2si[3]) CtlData2readch <= 3'd3;
          else if(RVALIDmi2si[4]) CtlData2readch <= 3'd4;
          else if(RVALIDmi2si[5]) CtlData2readch <= 3'd5;
    end
end



//MUX TYPE 01 was Generated 
