                 RREADYsi2mi[3] <= 1'b0;
                 RREADYsi2mi[4] <= 1'b0;
                 RREADYsi2mi[5] <= 1'b0;
            end
        3'd2:   
            begin
                 RREADYsi2mi[0] <= 1'b0;
                 RREADYsi2mi[1] <= 1'b0;
                 RREADYsi2mi[2] <= RREADYm2si ;
                 RREADYsi2mi[3] <= 1'b0;
                 RREADYsi2mi[4] <= 1'b0;
                 RREADYsi2mi[5] <= 1'b0;
            end
